import subprocess
import json
import os
from datetime import datetime

def execute(message: str, task_type: str = 'auto'):
    """Execute AI task using local DuckBot system"""
    try:
        # Try to connect to local DuckBot server first
        import requests

        # Check if DuckBot WebUI is running
        try:
            token_response = requests.get('http://localhost:8787/token', timeout=5)
            if token_response.status_code == 200:
                token = token_response.json().get('token')
                if token:
                    # Send request to DuckBot server
                    headers = {'Authorization': f'Bearer {token}'}
                    data = {'message': message, 'kind': task_type, 'risk': 'medium'}

                    response = requests.post('http://localhost:8787/chat', headers=headers, data=data, timeout=30)

                    if response.status_code == 200:
                        result = response.json()
                        if result.get('success'):
                            ai_response = result.get('response', 'No response')
                            model = result.get('model', 'unknown')
                            confidence = result.get('confidence', 0)

                            return f'🤖 **DuckBot AI Response:**\n\n{ai_response}\n\n📊 *Model: {model} | Confidence: {confidence:.2f}*'
                        else:
                            return f'❌ AI Error: {result.get("response", "Unknown error")}'
        except:
            pass

        # Fallback: Use local Python execution for basic tasks
        if task_type == 'code' and any(keyword in message.lower() for keyword in ['python', 'code', 'script', 'function']):
            return f'💻 **Code Analysis:**\n\nI can help you with Python code analysis. Please provide the specific code you\'d like me to analyze or help you write.'

        elif task_type == 'reasoning' or 'why' in message.lower() or 'explain' in message.lower():
            return f'🧠 **Reasoning Response:**\n\nBased on your question "{message}", I can provide logical analysis and explanations. This appears to be a request for detailed reasoning about a specific topic.'

        elif task_type == 'summary' or 'summarize' in message.lower():
            return f'📝 **Summary:**\n\nI can help summarize content. Please provide the text or information you\'d like me to summarize.'

        else:
            # General AI response
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            return f'🤖 **DuckBot AI Response** ({timestamp})\n\nI received your message: "{message}"\n\nI\'m currently operating in offline mode as the DuckBot server may not be running. For full AI capabilities, please ensure DuckBot WebUI is running on localhost:8787.\n\nType: {task_type}\n\nYou can also use other DuckBot functions for system management and monitoring.'

    except Exception as e:
        return f'❌ Error executing AI task: {str(e)}'

import os
import json
from pathlib import Path

def execute(file_path: str, analysis_type: str = 'info'):
    """Analyze files in the DuckBot system"""
    try:
        # Find DuckBot directory
        possible_dirs = [
            Path('~/Desktop/DuckBot-Consolidated-v4.2').expanduser(),
            Path('~/Desktop/DuckBot-v3.1.0').expanduser(),
            Path('~/Desktop/DuckBot').expanduser(),
            Path.cwd()
        ]

        duckbot_dir = None
        for dir_path in possible_dirs:
            if dir_path.exists():
                duckbot_dir = dir_path
                break

        if not duckbot_dir:
            return '❌ DuckBot directory not found. Please ensure DuckBot is installed.'

        full_path = duckbot_dir / file_path

        if not full_path.exists():
            return f'❌ File not found: {full_path}'

        if analysis_type == 'info':
            # Basic file information
            stat = full_path.stat()
            size_kb = stat.st_size / 1024

            result = f'📄 **File Analysis: {file_path}**\n\n'
            result += f'• **Size:** {size_kb:.1f} KB\n'
            result += f'• **Type:** {"Directory" if full_path.is_dir() else "File"}\n'
            result += f'• **Modified:** {datetime.fromtimestamp(stat.st_mtime)}\n'

            if full_path.suffix:
                result += f'• **Extension:** {full_path.suffix}\n'

                # File type specific info
                if full_path.suffix == '.py':
                    try:
                        with open(full_path, 'r', encoding='utf-8') as f:
                            lines = f.readlines()
                        result += f'• **Lines of Code:** {len(lines)}\n'

                        # Count functions/classes
                        functions = sum(1 for line in lines if line.strip().startswith('def '))
                        classes = sum(1 for line in lines if line.strip().startswith('class '))
                        result += f'• **Functions:** {functions}\n'
                        result += f'• **Classes:** {classes}\n'
                    except:
                        result += '• **Content:** Could not read file\n'

                elif full_path.suffix == '.json':
                    try:
                        with open(full_path, 'r', encoding='utf-8') as f:
                            data = json.load(f)
                        result += f'• **JSON Keys:** {len(data) if isinstance(data, dict) else "Not a dict"}\n'
                    except:
                        result += '• **Content:** Invalid JSON or unreadable\n'

                elif full_path.suffix in ['.txt', '.md', '.bat']:
                    try:
                        with open(full_path, 'r', encoding='utf-8') as f:
                            lines = f.readlines()
                        result += f'• **Lines:** {len(lines)}\n'
                    except:
                        result += '• **Content:** Could not read file\n'

            return result

        elif analysis_type == 'content' and full_path.is_file():
            # Show file content (first 1000 chars)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                if len(content) > 1000:
                    content = content[:1000] + '\n... [truncated]'

                return f'📝 **File Content: {file_path}**\n\n```\n{content}\n```'
            except Exception as e:
                return f'❌ Could not read file content: {str(e)}'

        elif analysis_type == 'structure':
            # Show directory structure
            if full_path.is_dir():
                result = f'📁 **Directory Structure: {file_path}**\n\n'

                def list_directory(path, indent=0):
                    items = []
                    try:
                        for item in path.iterdir():
                            prefix = '  ' * indent + ('📁 ' if item.is_dir() else '📄 ')
                            items.append(prefix + item.name)
                            if item.is_dir() and indent < 2:  # Limit depth
                                items.extend(list_directory(item, indent + 1))
                    except PermissionError:
                        items.append('  ' * indent + '⚠️ Permission denied')
                    return items

                structure = list_directory(full_path)
                result += '\n'.join(structure[:50])  # Limit to 50 items
                if len(structure) > 50:
                    result += f'\n... and {len(structure) - 50} more items'

                return result
            else:
                return f'❌ Path is not a directory: {file_path}'

        else:
            return f'❌ Unsupported analysis type: {analysis_type}'

    except Exception as e:
        return f'❌ Error analyzing file: {str(e)}'

import subprocess
import os
import time
from pathlib import Path

def execute(service_name: str, action: str):
    """Manage DuckBot services"""
    try:
        # Find DuckBot directory
        possible_dirs = [
            Path('~/Desktop/DuckBot-Consolidated-v4.2').expanduser(),
            Path('~/Desktop/DuckBot-v3.1.0').expanduser(),
            Path('~/Desktop/DuckBot').expanduser()
        ]

        duckbot_dir = None
        for dir_path in possible_dirs:
            if dir_path.exists():
                duckbot_dir = dir_path
                break

        if not duckbot_dir:
            return '❌ DuckBot directory not found'

        # Service configurations
        services = {
            'webui': {
                'start_script': 'START_ENHANCED_DUCKBOT.bat',
                'port': 8787,
                'description': 'DuckBot WebUI'
            },
            'comfyui': {
                'port': 8888,
                'description': 'ComfyUI'
            },
            'n8n': {
                'port': 3000,
                'description': 'n8n Workflow Automation'
            },
            'jupyter': {
                'port': 8888,
                'description': 'Jupyter Notebook'
            },
            'lm_studio': {
                'port': 6333,
                'description': 'LM Studio'
            },
            'ollama': {
                'port': 11434,
                'description': 'Ollama'
            }
        }

        if service_name not in services:
            return f'❌ Unknown service: {service_name}. Available: {list(services.keys())}'

        service = services[service_name]

        if action == 'status':
            # Check if service is running by checking port
            try:
                result = subprocess.run(['netstat', '-ano', '|', 'findstr', f':{service["port"]}'], 
                                      shell=True, capture_output=True, text=True, timeout=5)
                if result.returncode == 0 and result.stdout.strip():
                    return f'✅ {service["description"]} is running on port {service["port"]}\n{result.stdout.strip()}'
                else:
                    return f'❌ {service["description"]} is not running on port {service["port"]}'
            except Exception as e:
                return f'⚠️ Could not check status: {str(e)}'

        elif action == 'start':
            if service_name == 'webui' and 'start_script' in service:
                script_path = duckbot_dir / service['start_script']
                if script_path.exists():
                    return f'🚀 Starting {service["description"]}...\n\nTo start: Run {script_path}\n\nThis will open the DuckBot WebUI in your default browser.'
                else:
                    return f'❌ Start script not found: {script_path}'
            else:
                return f'🚀 To start {service["description"]}:\n\nPlease start the service manually. It should run on port {service["port"]}.\n\nTypically this involves running the application\'s startup script or executable.'

        elif action == 'stop':
            try:
                # Find process using the port
                result = subprocess.run(['netstat', '-ano', '|', 'findstr', f':{service["port"]}'], 
                                      shell=True, capture_output=True, text=True, timeout=5)
                if result.returncode == 0 and result.stdout.strip():
                    # Extract PID from netstat output
                    lines = result.stdout.strip().split('\n')
                    for line in lines:
                        if f':{service["port"]}' in line:
                            parts = line.split()
                            if len(parts) >= 5:
                                pid = parts[-1]
                                try:
                                    subprocess.run(['taskkill', '/F', '/PID', pid], check=True, timeout=10)
                                    return f'✅ Stopped {service["description"]} (PID: {pid})'
                                except subprocess.CalledProcessError:
                                    return f'⚠️ Could not stop process {pid}'
                    return f'❌ Could not find process for port {service["port"]}'
                else:
                    return f'ℹ️ {service["description"]} is not running'
            except Exception as e:
                return f'❌ Error stopping service: {str(e)}'

        elif action == 'restart':
            # Stop then start
            stop_result = execute(service_name, 'stop')
            time.sleep(2)  # Wait for stop to complete
            start_result = execute(service_name, 'start')
            return f'🔄 **Restart {service["description"]}:**\n\nStop: {stop_result}\n\nStart: {start_result}'

        else:
            return f'❌ Unknown action: {action}'

    except Exception as e:
        return f'❌ Error managing service: {str(e)}'
